public class Flag {
    private volatile boolean stopped;          // 状态标志：一写多读
    public void stop() { stopped = true; }
    public void run() { while (!stopped) { /* work */ } }

    private static volatile Flag INSTANCE;     // DCL 必须 volatile
    public static Flag get() {
        if (INSTANCE == null) {
            synchronized (Flag.class) {
                if (INSTANCE == null) INSTANCE = new Flag();
            }
        }
        return INSTANCE;
    }
}
